// ServerServiceServer is the server API for ServerService service.
// All implementations must embed UnimplementedServerServiceServer
// for forward compatibility.
//
// ServerService reports what the server can host. Added in protocol 2.
type ServerServiceServer interface {
	GetCapabilities(context.Context, *GetCapabilitiesRequest) (*GetCapabilitiesResponse, error)
	// The server's scheduled jobs: commands cron runs as a user, apart from any site. Added in protocol 5.
	ListScheduledJobs(context.Context, *ListScheduledJobsRequest) (*ListScheduledJobsResponse, error)
	// Replaces the whole list. Fails with FAILED_PRECONDITION when it changed since expected_revision.
	PutScheduledJobs(context.Context, *PutScheduledJobsRequest) (*PutScheduledJobsResponse, error)
	// The server's background processes: commands systemd keeps running as a user, apart from any site. Added in
	// protocol 10.
	ListBackgroundProcesses(context.Context, *ListBackgroundProcessesRequest) (*ListBackgroundProcessesResponse, error)
	// Replaces the whole list; new and changed ones restart. Fails with FAILED_PRECONDITION when it changed since
	// expected_revision.
	PutBackgroundProcesses(context.Context, *PutBackgroundProcessesRequest) (*PutBackgroundProcessesResponse, error)
	// Restarts every copy of one without waiting. Fails with FAILED_PRECONDITION when it's stopped. Added in protocol 19.
	RestartBackgroundProcess(context.Context, *RestartBackgroundProcessRequest) (*RestartBackgroundProcessResponse, error)
	// Installs the FrankenPHP release this agent pins at /usr/local/bin/frankenphp for Laravel Octane, unless it's there
	// already: ~175 MB from GitHub, checked against its published SHA-256. Fails with FAILED_PRECONDITION when the
	// download fails or doesn't match. Added in protocol 19.
	InstallFrankenPHP(context.Context, *InstallFrankenPHPRequest) (*InstallFrankenPHPResponse, error)
	// The timezone and whether Redis asks for a password. Added in protocol 14.
	GetServerSettings(context.Context, *GetServerSettingsRequest) (*GetServerSettingsResponse, error)
	// Changes the system timezone; cron restarts so scheduled jobs follow it.
	SetTimezone(context.Context, *SetTimezoneRequest) (*SetTimezoneResponse, error)
	// Sets Redis's password, or removes it when empty, and restarts Redis.
	SetRedisPassword(context.Context, *SetRedisPasswordRequest) (*SetRedisPasswordResponse, error)
	// The system services ServerDog installs (Nginx, databases, Redis, PHP-FPM…) and whether each runs. Added in
	// protocol 15.
	ListSystemServices(context.Context, *ListSystemServicesRequest) (*ListSystemServicesResponse, error)
	// Starts, stops, restarts or reloads one of them. A failure carries the end of its journal.
	ControlSystemService(context.Context, *ControlSystemServiceRequest) (*ControlSystemServiceResponse, error)
	// Answers, then reboots the server a moment later.
	RebootServer(context.Context, *RebootServerRequest) (*RebootServerResponse, error)
	// Load, memory, disk and network traffic over a past span, recorded once a minute for seven days. Added in protocol 12.
	GetMetricHistory(context.Context, *GetMetricHistoryRequest) (*GetMetricHistoryResponse, error)
	// The server's PHP limits, applied to every installed version and to Nginx. Added in protocol 11.
	GetPHPSettings(context.Context, *GetPHPSettingsRequest) (*GetPHPSettingsResponse, error)
	// Fails with FAILED_PRECONDITION when they changed since expected_revision.
	PutPHPSettings(context.Context, *PutPHPSettingsRequest) (*PutPHPSettingsResponse, error)
	// A user's Composer logins: the http-basic part of ~/.composer/auth.json. Added in protocol 11.
	GetComposerCredentials(context.Context, *GetComposerCredentialsRequest) (*GetComposerCredentialsResponse, error)
	// Replaces them and keeps the rest of the file.
	PutComposerCredentials(context.Context, *PutComposerCredentialsRequest) (*PutComposerCredentialsResponse, error)
	// A user's npm registry tokens in ~/.npmrc. Added in protocol 11.
	GetNPMCredentials(context.Context, *GetNPMCredentialsRequest) (*GetNPMCredentialsResponse, error)
	// Replaces them and keeps the file's other lines.
	PutNPMCredentials(context.Context, *PutNPMCredentialsRequest) (*PutNPMCredentialsResponse, error)
	// The chat webhook deploy and backup outcomes are posted to. Added in protocol 5.
	GetNotifications(context.Context, *GetNotificationsRequest) (*GetNotificationsResponse, error)
	// Fails with FAILED_PRECONDITION when the settings changed since expected_revision.
	PutNotifications(context.Context, *PutNotificationsRequest) (*PutNotificationsResponse, error)
	// Posts a test message to webhook_url, saved or not.
	TestNotifications(context.Context, *TestNotificationsRequest) (*TestNotificationsResponse, error)
	// The logs on this server: its own (journal, Nginx, PHP-FPM, database) and each site's. Added in protocol 6.
	ListLogs(context.Context, *ListLogsRequest) (*ListLogsResponse, error)
	// The last lines of one, oldest first. Fails with NOT_FOUND for an id ListLogs didn't return.
	ReadLog(context.Context, *ReadLogRequest) (*ReadLogResponse, error)
	// The ufw rules added in the app, and the others listed read-only. Added in protocol 6.
	GetFirewall(context.Context, *GetFirewallRequest) (*GetFirewallResponse, error)
	// Replaces the app's rules. Fails with FAILED_PRECONDITION when they changed since expected_revision.
	PutFirewall(context.Context, *PutFirewallRequest) (*PutFirewallResponse, error)
	// The SSH keys added in the app to root's and the site users' authorized_keys, and the others. Added in protocol 6.
	GetSSHKeys(context.Context, *GetSSHKeysRequest) (*GetSSHKeysResponse, error)
	// Replaces the app's keys. Fails with FAILED_PRECONDITION when they changed since expected_revision.
	PutSSHKeys(context.Context, *PutSSHKeysRequest) (*PutSSHKeysResponse, error)
	// The installed and installable PHP versions. Added in protocol 6.
	GetPHPVersions(context.Context, *GetPHPVersionsRequest) (*GetPHPVersionsResponse, error)
	// Installs a version; it takes a minute or two. Installing an installed version does nothing.
	InstallPHPVersion(context.Context, *InstallPHPVersionRequest) (*InstallPHPVersionResponse, error)
	// Fails with INVALID_ARGUMENT for a version a site runs on, the php command's, or the last one.
	RemovePHPVersion(context.Context, *RemovePHPVersionRequest) (*RemovePHPVersionResponse, error)
	// Points the php command at an installed version.
	SetCLIPHPVersion(context.Context, *SetCLIPHPVersionRequest) (*SetCLIPHPVersionResponse, error)
	// The private network: the address the database, Redis, Memcached and Meilisearch also listen on, and the servers
	// allowed to reach them. Added in protocol 9.
	GetNetwork(context.Context, *GetNetworkRequest) (*GetNetworkResponse, error)
	// Moves the services to the address and replaces the servers allowed in. Fails with FAILED_PRECONDITION when the
	// settings changed since expected_revision. A service that doesn't come back gets its previous settings again.
	PutNetwork(context.Context, *PutNetworkRequest) (*PutNetworkResponse, error)
	// Dials address:port over TCP from this server, within 5 seconds. Added in protocol 9.
	CheckConnection(context.Context, *CheckConnectionRequest) (*CheckConnectionResponse, error)
	// Automatic updates: their settings, unattended-upgrades' last run, pending updates and whether an installed one
	// waits for a restart. Added in protocol 18.
	GetUpdates(context.Context, *GetUpdatesRequest) (*GetUpdatesResponse, error)
	// Fails with FAILED_PRECONDITION when they changed since expected_revision.
	PutUpdateSettings(context.Context, *PutUpdateSettingsRequest) (*PutUpdateSettingsResponse, error)
	// What is wrong on the server right now. The agent looks only when asked and keeps the answer for a minute.
	// Added in protocol 19.
	GetInsights(context.Context, *GetInsightsRequest) (*GetInsightsResponse, error)
	// Applies a fixable insight's fix. Fails with FAILED_PRECONDITION when the insight is gone or has no fix.
	FixInsight(context.Context, *FixInsightRequest) (*FixInsightResponse, error)
	// Meilisearch's settings file, without the master key and listen address ServerDog manages. Added in protocol 23.
	GetMeilisearchConfig(context.Context, *GetMeilisearchConfigRequest) (*GetMeilisearchConfigResponse, error)
	// Saves the settings and restarts Meilisearch; if it doesn't come back, the previous file returns. Fails with
	// INVALID_ARGUMENT for a line that isn't a MEILI_ setting or that sets a managed one.
	PutMeilisearchConfig(context.Context, *PutMeilisearchConfigRequest) (*PutMeilisearchConfigResponse, error)
	// Meilisearch's API keys, read with its master key.
	ListMeilisearchKeys(context.Context, *ListMeilisearchKeysRequest) (*ListMeilisearchKeysResponse, error)
	mustEmbedUnimplementedServerServiceServer()
}

